  "implementation": "def solve(case):
    # Extract fields
    nodes = case.get('nodes')
    required_symbols = case.get('required_symbols')
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError('Invalid case structure')
    # Build node map and children map
    node_map = {}
    children_map = {}  # parent -> list of child ids
    for node in nodes:
        nid = node.get('id')
        if not isinstance(nid, str):
            raise ValueError('Node id must be a string')
        node_map[nid] = node
        parent = node.get('parent')
        if parent is not None:
            children_map.setdefault(parent, []).append(nid)
    # Validate required symbols
    symbol_counts = {}
    for sym in required_symbols:
        symbol_counts[sym] = 0
    for node in nodes:
        sym = node.get('symbol')
        if sym in symbol_counts:
            symbol_counts[sym] += 1
    for sym, count in symbol_counts.items():
        if count == 0:
            raise ValueError(f'Required symbol {sym} not present in any node')
    # Initial retained set and symbol counts (mutable)
    retained = set(node_map.keys())
    current_counts = dict(symbol_counts)  # copy
    # Sort nodes: depth descending, then node id ascending (string)
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed_order = []
    for node in sorted_nodes:
        nid = node['id']
        if nid not in retained:
            continue  # already removed (due to parent removal earlier? but shouldn't happen)
        # Check conditions
        if not node.get('removable', False):
            continue
        if node.get('parent') is None:  # root
            continue
        # Check retained children
        children = children_map.get(nid, [])
        has_retained_child = any(cid in retained for cid in children)
        if has_retained_child:
            continue
        # Check required symbols after tentative removal
        sym = node['symbol']
        tentative_counts = dict(current_counts)
        tentative_counts[sym] -= 1
        if any(tentative_counts.get(s, 0) == 0 for s in required_symbols):
            continue
        # Remove node
        removed_order.append(nid)
        retained.remove(nid)
        current_counts[sym] -= 1
    # Sort retained IDs lexicographically
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed_order,
        'retained_node_ids': retained_sorted
    }"
}
